<?php
namespace PortOpener\Http\Middleware;use Closure;use Illuminate\Http\Request;use PortOpener\Models\{NodeCredential,NodePolicy};
class AuthenticateNodeService {public function handle(Request $request,Closure $next){$token=$request->bearerToken();abort_unless(is_string($token)&&preg_match('/^[a-f0-9]{64}$/D',$token),401,'Service authentication required.');$credential=NodeCredential::where('token_hash',hash('sha256',$token))->whereNull('revoked_at')->where('expires_at','>',now())->first();abort_unless($credential,401,'Service authentication failed.');$policy=NodePolicy::where('node_id',$credential->node_id)->first();abort_unless($policy && $policy->connection_mode==='outbound' && $policy->service_enabled,403,'Node service is disabled.');$request->attributes->set('port_opener_credential',$credential);$request->attributes->set('port_opener_policy',$policy);$policy->forceFill(['last_contact_at'=>now()])->saveQuietly();return $next($request);}}
